## 4. 在遊戲引擎中的實作

### Unity (C#)

```csharp
public class Node {
    public Vector2Int pos;
    public List<Node> neighbors;
    public float gCost, hCost;
    public Node parent;
}

public List<Node> FindPath(Node start, Node goal) {
    var openSet = new Heap<Node>(maxNodes);
    var closedSet = new HashSet<Node>();

    openSet.Add(start);

    while (openSet.Count > 0) {
        var current = openSet.RemoveFirst(); // lowest fCost
        closedSet.Add(current);

        if (current == goal) {
            return RetracePath(start, goal);
        }

        foreach (var neighbor in current.neighbors) {
            if (closedSet.Contains(neighbor)) continue;

            float tentativeG = current.gCost + GetDistance(current, neighbor);
            if (tentativeG < neighbor.gCost || !openSet.Contains(neighbor)) {
                neighbor.gCost = tentativeG;
                neighbor.hCost = GetDistance(neighbor, goal);
                neighbor.parent = current;

                if (!openSet.Contains(neighbor))
                    openSet.Add(neighbor);
                else
                    openSet.UpdateItem(neighbor);
            }
        }
    }
    return null; // no path
}
```

> **提示**  
> - `Heap<T>` 是一個優先佇列，常用於 A*。  
> - `GetDistance` 可以是曼哈頓距離或歐氏距離。  
> - 若你使用 Unity 的 NavMesh，則可以直接使用 `NavMeshAgent` 來尋路，省去手動實作。

### Godot (GDScript)

```gdscript
func find_path(grid, start, goal):
    var open = []
    var closed = {}
    var came_from = {}
    var g_score = {}
    g_score[start] = 0

    open.append([heuristic(start, goal), start])

    while open.size() > 0:
        open.sort_custom(self, "_sort_by_f")
        var current = open.pop_front()[1]

        if current == goal:
            return reconstruct_path(came_from, current)

        closed[current] = true

        for neighbor in get_neighbors(grid, current):
            if closed.has(neighbor):
                continue
            var tentative_g = g_score[current] + 1
            if not g_score.has(neighbor) or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                var f = tentative_g + heuristic(neighbor, goal)
                open.append([f, neighbor])

    return null

func heuristic(a, b):
    return abs(a.x - b.x) + abs(a.y - b.y)
```

